def _unpack(blob):
    return zlib.decompress(base64.b64decode("".join(blob.split())))


# =====================================================================
#  files & paths
# =====================================================================
def data_dir():
    root = os.environ.get("LOCALAPPDATA") or os.path.expanduser("~/.local/share")
    path = os.path.join(root, "ArtStudioPro")
    os.makedirs(path, exist_ok=True)
    return path


def installed_script():
    return os.path.join(data_dir(), "ArtStudioPro.pyw")


def write_icon():
    path = os.path.join(data_dir(), "icon.ico")
    with open(path, "wb") as f:
        f.write(_unpack(_ICON))
    return path


def write_logo():
    path = os.path.join(data_dir(), "logo.png")
    with open(path, "wb") as f:
        f.write(base64.b64decode("".join(_LOGO.split())))
    return path


def pyw_exe():
    pyw = os.path.join(os.path.dirname(sys.executable), "pythonw.exe")
    return pyw if os.path.exists(pyw) else sys.executable


# =====================================================================
#  installing: components, copy, shortcuts
# =====================================================================
def ensure_webview():
    if importlib.util.find_spec("webview"):
        return
    r = subprocess.run([sys.executable, "-m", "pip", "install", "--disable-pip-version-check",
                        "pywebview"], capture_output=True, text=True, creationflags=NO_WINDOW)
    if r.returncode != 0:
        raise RuntimeError("Could not download the helper (pywebview).\n"
                           "Check your internet and try again.\n\n" + (r.stderr or r.stdout)[-300:])


def run_powershell(script):
    ps1 = os.path.join(data_dir(), "setup_step.ps1")
    with open(ps1, "w", encoding="utf-8-sig") as f:
        f.write(script)
    r = subprocess.run(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-File", ps1],
                       capture_output=True, text=True, creationflags=NO_WINDOW)
    try:
        os.remove(ps1)
    except OSError:
        pass
    if r.returncode != 0:
        raise RuntimeError("Could not create the shortcut.\n\n" + (r.stderr or r.stdout)[-300:])


_PS_MAKE = r"""
$ErrorActionPreference = 'Stop'
$sh = New-Object -ComObject WScript.Shell
function Make-Link($folder) {
  $s = $sh.CreateShortcut((Join-Path $folder '{NAME}.lnk'))
  $s.TargetPath = '{PYW}'
  $s.Arguments = '"{SCRIPT}" --run'
  $s.WorkingDirectory = '{DIR}'
  $s.IconLocation = '{ICO},0'
  $s.Description = '{NAME}'
  $s.Save()
}
"""
_PS_DESKTOP = "Make-Link ([Environment]::GetFolderPath('Desktop'))\n"
_PS_MENU = "Make-Link ([Environment]::GetFolderPath('Programs'))\n"
_PS_REMOVE = r"""
Remove-Item -Force -ErrorAction SilentlyContinue (Join-Path ([Environment]::GetFolderPath('Desktop')) '{NAME}.lnk')
Remove-Item -Force -ErrorAction SilentlyContinue (Join-Path ([Environment]::GetFolderPath('Programs')) '{NAME}.lnk')
"""


def make_shortcuts(script, ico, desktop, menu):
    if os.name == "nt":
        q = lambda s: s.replace("'", "''")
        ps = (_PS_MAKE + (_PS_DESKTOP if desktop else "") + (_PS_MENU if menu else ""))
        for k, v in {"{NAME}": APP_NAME, "{PYW}": q(pyw_exe()), "{SCRIPT}": q(script),
                     "{DIR}": q(os.path.dirname(script)), "{ICO}": q(ico)}.items():
            ps = ps.replace(k, v)
        run_powershell(ps)
    elif sys.platform.startswith("linux"):
        entry = ("[Desktop Entry]\nType=Application\nName=%s\nComment=Digital Painting\n"
                 "Exec=\"%s\" \"%s\" --run\nIcon=%s\nTerminal=false\nCategories=Graphics;\n"
                 % (APP_NAME, sys.executable, script, write_logo()))
        targets = []
        if desktop:
            targets.append(os.path.expanduser("~/Desktop"))
        if menu:
            targets.append(os.path.expanduser("~/.local/share/applications"))
        for folder in targets:
            os.makedirs(folder, exist_ok=True)
            p = os.path.join(folder, APP_NAME + ".desktop")
            with open(p, "w") as f:
                f.write(entry)
            os.chmod(p, 0o755)


def install(desktop, menu, report):
    report(6, "Getting ready...")
    ico = write_icon()
    write_logo()
    report(14, "Downloading components...")
    ensure_webview()
    report(78, "Copying ArtStudio Pro...")
    target = installed_script()
    if os.path.abspath(__file__) != os.path.abspath(target):
        shutil.copyfile(os.path.abspath(__file__), target)
    report(90, "Adding your logo to the desktop...")
    make_shortcuts(target, ico, desktop, menu)
    report(100, "Done!")
    return target


def uninstall():
    if os.name == "nt":
        try:
            run_powershell(_PS_REMOVE.replace("{NAME}", APP_NAME))
        except RuntimeError:
            pass
    else:
        for p in ("~/Desktop", "~/.local/share/applications"):
            try:
                os.remove(os.path.join(os.path.expanduser(p), APP_NAME + ".desktop"))
            except OSError:
                pass
    for name in ("ArtStudioPro.pyw", "icon.ico", "logo.png"):
        try:
            os.remove(os.path.join(data_dir(), name))
        except OSError:
            pass
    print("ArtStudio Pro removed. (Your saved drawings were kept in %s)" % data_dir())


# =====================================================================
#  the setup window
# =====================================================================
def _mix(c1, c2, t):
    a = [int(c1[i:i + 2], 16) for i in (1, 3, 5)]
    b = [int(c2[i:i + 2], 16) for i in (1, 3, 5)]
    return "#%02x%02x%02x" % tuple(int(a[i] + (b[i] - a[i]) * t) for i in range(3))


class Installer:
    BG, CARD, TX, MU, AC, OK = "#000000", "#1c1c1e", "#f5f5f7", "#8e8e93", "#0a84ff", "#30d158"
    GRAD = ("#5ac8fa", "#bf5af2", "#ff6482")  # same colors as your splash logo
    FONT = "Segoe UI"

    def __init__(self):
        import tkinter as tk
        self.tk = tk
        self.root = r = tk.Tk()
        r.title(APP_NAME + " Setup  v" + APP_VERSION)
        w, h = 480, 640
        r.geometry("%dx%d+%d+%d" % (w, h, (r.winfo_screenwidth() - w) // 2,
                                    max(10, (r.winfo_screenheight() - h) // 3)))
        r.configure(bg=self.BG)
        r.resizable(False, False)
        if os.name == "nt":
            try:
                r.iconbitmap(write_icon())
            except Exception:
                pass
        self.logo = tk.PhotoImage(data="".join(_LOGO.split()))
        self.desk = tk.BooleanVar(value=True)
        self.menu = tk.BooleanVar(value=True)
        self.q = queue.Queue()
        self.frame = None
        self.fade(0.0)
        self.welcome()

    def run(self):
        self.root.mainloop()

    # ----- small helpers -----
    def fade(self, a):
        try:
            self.root.attributes("-alpha", min(a, 1.0))
        except Exception:
            return
        if a < 1:
            self.root.after(16, lambda: self.fade(a + 0.07))

    def page(self):
        if self.frame:
            self.frame.destroy()
        self.frame = self.tk.Frame(self.root, bg=self.BG)
        self.frame.pack(fill="both", expand=True)
        return self.frame

    def text(self, parent, s, size=11, bold=False, color=None, pady=(0, 0), wrap=380):
        self.tk.Label(parent, text=s, bg=self.BG, fg=color or self.TX, wraplength=wrap,
                      justify="center", font=(self.FONT, size, "bold" if bold else "normal")
                      ).pack(pady=pady)

    def button(self, parent, s, cmd, primary=True, pady=(10, 0)):
        base = self.AC if primary else self.CARD
        hover = "#3395ff" if primary else "#2c2c2e"
        b = self.tk.Button(parent, text=s, command=cmd, bg=base, fg="white", bd=0,
                           activebackground=hover, activeforeground="white", relief="flat",
                           cursor="hand2", width=28, pady=11, font=(self.FONT, 11, "bold"))
        b.bind("<Enter>", lambda e: b.config(bg=hover))
        b.bind("<Leave>", lambda e: b.config(bg=base))
        b.pack(pady=pady)

    def header(self, f, title, sub):
        self.tk.Label(f, image=self.logo, bg=self.BG).pack(pady=(46, 0))
        self.text(f, title, 26, True, pady=(14, 0))
        self.text(f, sub, 11, color=self.MU, pady=(4, 0))

    # ----- pages -----
    def welcome(self):
        f = self.page()
        already = os.path.exists(installed_script())
        self.header(f, APP_NAME, "Digital Painting")
        box = self.tk.Frame(f, bg=self.CARD, padx=22, pady=14)
        box.pack(pady=(34, 0))
        for var, label in ((self.desk, "Add the logo to my desktop"),
                           (self.menu, "Add to the Start menu")):
            self.tk.Checkbutton(box, text=label, variable=var, bg=self.CARD, fg=self.TX,
                                selectcolor="#000000", activebackground=self.CARD,
                                activeforeground=self.TX, bd=0, highlightthickness=0,
                                font=(self.FONT, 11), anchor="w", width=28).pack(pady=3)
        self.button(f, "Update" if already else "Install", self.start, pady=(26, 0))
        if already:
            self.button(f, "Open ArtStudio Pro", self.open_app, primary=False, pady=(10, 0))
        self.text(f, "Installs only for you. No admin needed.", 9, color=self.MU, pady=(18, 0))

    def progress_page(self):
        f = self.page()
        self.header(f, "Installing...", "Please wait a moment")
        self.status = self.tk.Label(f, text="Getting ready...", bg=self.BG, fg=self.MU,
                                    font=(self.FONT, 10))
        self.status.pack(pady=(40, 10))
        self.bar = self.tk.Canvas(f, width=340, height=10, bg=self.BG, highlightthickness=0)
        self.bar.pack()
        self.target, self.shown, self.finishing = 0.0, 0.0, False

    def draw_bar(self):
        c = self.bar
        c.delete("all")
        c.create_line(5, 5, 335, 5, width=8, capstyle="round", fill=self.CARD)
        n = int(330 * self.shown / 100)
        for x in range(0, n, 3):
            t = x / 330
            col = (_mix(self.GRAD[0], self.GRAD[1], t * 2) if t < .5
                   else _mix(self.GRAD[1], self.GRAD[2], (t - .5) * 2))
            c.create_line(5 + x, 5, min(8 + x, 5 + n), 5, width=8, fill=col)

    def start(self):
        desk, menu = self.desk.get(), self.menu.get()
        self.progress_page()
        threading.Thread(target=self.work, args=(desk, menu), daemon=True).start()
        self.poll()

    def work(self, desk, menu):
        try:
            install(desk, menu, lambda p, t: self.q.put(("p", p, t)))
            self.q.put(("done",))
        except Exception as e:
            self.q.put(("err", str(e)))

    def poll(self):
        try:
            while True:
                m = self.q.get_nowait()
                if m[0] == "p":
                    self.target = m[1]
                    self.status.config(text=m[2])
                elif m[0] == "done":
                    self.target, self.finishing = 100.0, True
                else:
                    return self.error_page(m[1])
        except queue.Empty:
            pass
        if self.shown < self.target:
            self.shown = min(self.target, self.shown + max(0.25, (self.target - self.shown) * 0.08))
        elif not self.finishing and self.shown < min(self.target + 10, 94):
            self.shown += 0.04  # slow crawl while a long step runs
        self.draw_bar()
        if self.finishing and self.shown >= 99.9:
            return self.root.after(350, self.done_page)
        self.root.after(16, self.poll)

    def done_page(self):
        f = self.page()
        c = self.tk.Canvas(f, width=120, height=120, bg=self.BG, highlightthickness=0)
        c.pack(pady=(70, 0))
        self.text(f, "You're all set!", 26, True, pady=(14, 0))
        self.text(f, "Look for the ArtStudio Pro logo on your desktop.", 11, color=self.MU,
                  pady=(6, 0))
        self.button(f, "Open ArtStudio Pro", self.open_app, pady=(46, 0))
        self.button(f, "Close", self.root.destroy, primary=False, pady=(10, 0))
        self.pop(c, 0)

    def pop(self, c, step):  # green circle + check mark animation
        c.delete("all")
        k = min(1.0, step / 14)
        e = 1 - (1 - k) ** 3
        r = 46 * e
        c.create_oval(60 - r, 60 - r, 60 + r, 60 + r, fill=self.OK, outline="")
        if k >= 0.55:
            p = min(1.0, (k - 0.55) / 0.45)
            pts = [(40, 62), (54, 76), (82, 46)]
            seg = [pts[0]]
            if p <= 0.4:
                t = p / 0.4
                seg.append((pts[0][0] + (pts[1][0] - pts[0][0]) * t,
                            pts[0][1] + (pts[1][1] - pts[0][1]) * t))
            else:
                t = (p - 0.4) / 0.6
                seg += [pts[1], (pts[1][0] + (pts[2][0] - pts[1][0]) * t,
                                 pts[1][1] + (pts[2][1] - pts[1][1]) * t)]
            c.create_line(*[v for pt in seg for v in pt], fill="white", width=7,
                          capstyle="round", joinstyle="round")
        if step < 14:
            self.root.after(20, lambda: self.pop(c, step + 1))

    def error_page(self, msg):
        f = self.page()
        self.header(f, "Oops", "Something went wrong")
        self.text(f, msg, 10, color="#ff6482", pady=(24, 0))
        self.button(f, "Try again", self.welcome, pady=(26, 0))

    def open_app(self):
        script = installed_script()
        if not os.path.exists(script):
            script = os.path.abspath(__file__)
        subprocess.Popen([pyw_exe(), script, "--run"], cwd=os.path.dirname(script),
                         close_fds=True)
        self.root.destroy()


# =====================================================================
#  the app itself (your site in its own window)
# =====================================================================
def serve(page, preferred_port=47831):
    """Tiny local server. Fixed port = same address every launch, so the
    gallery / artworks saved by the site are still there next time."""
    class Handler(http.server.BaseHTTPRequestHandler):
        protocol_version = "HTTP/1.1"  # keep-alive = faster loads

        def do_GET(self):
            if self.path.split("?")[0] in ("/", "/index.html"):
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Content-Length", str(len(page)))
                self.send_header("Cache-Control", "no-store")
                self.end_headers()
                self.wfile.write(page)
            else:
                self.send_error(404)

        def log_message(self, *args):
            pass

    try:
        srv = http.server.ThreadingHTTPServer(("127.0.0.1", preferred_port), Handler)
    except OSError:
        srv = http.server.ThreadingHTTPServer(("127.0.0.1", 0), Handler)
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    return srv, "http://127.0.0.1:%d/" % srv.server_address[1]


def run_app():
    if sys.stdout is None:  # started without a console (pythonw / shortcut)
        sys.stdout = open(os.devnull, "w")
    if sys.stderr is None:
        sys.stderr = open(os.devnull, "w")
    if os.name == "nt":  # own taskbar entry with your logo (not the Python one)
        try:
            import ctypes
            ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID(APP_ID)
        except Exception:
            pass
    ensure_webview()
    os.environ.setdefault("WEBVIEW2_ADDITIONAL_BROWSER_ARGUMENTS",
                          "--enable-gpu-rasterization --ignore-gpu-blocklist --enable-zero-copy")
    import webview
    srv, url = serve(_unpack(_HTML))
    icon = write_icon()

    # let the site's "Download PNG / Download video" buttons save files
    webview.settings["ALLOW_DOWNLOADS"] = True
    webview.settings["OPEN_EXTERNAL_LINKS_IN_BROWSER"] = True

    window = webview.create_window(
        APP_NAME + " v" + APP_VERSION, url,
        width=1366, height=860, min_size=(900, 560),
        background_color="#000000",
        text_select=False,
        maximized=True,
    )

    def set_icon():  # logo in the title bar (Windows)
        try:
            import System.Drawing as D
            window.native.Icon = D.Icon(icon)
        except Exception:
            pass

    window.events.shown += set_icon
    webview.start(private_mode=False, storage_path=data_dir())
    srv.shutdown()


def build_exe():
    r"""python ArtStudioPro.py --build   ->   dist\ArtStudio Pro.exe"""
    work = os.path.join(data_dir(), "build")
    os.makedirs(work, exist_ok=True)
    ico = write_icon()
    subprocess.check_call([sys.executable, "-m", "pip", "install", "pywebview", "pyinstaller"])
    subprocess.check_call([
        sys.executable, "-m", "PyInstaller", "--noconsole", "--onefile",
        "--icon", ico, "--name", APP_NAME,
        "--distpath", os.path.join(os.getcwd(), "dist"),
        "--workpath", os.path.join(work, "tmp"),
        "--specpath", work,
        os.path.abspath(__file__),
    ])
    print("\nDone!  Your app:  dist\\%s.exe" % APP_NAME)


if __name__ == "__main__":
    args = sys.argv[1:]
    if "--build" in args:
        build_exe()
    elif "--uninstall" in args:
        uninstall()
    elif "--run" in args or FROZEN:
        run_app()
    else:
        try:
            Installer().run()
        except ImportError:  # no tkinter on this PC: just start the app
            run_app()
